  await page.evaluate(()=>{PlayroomFirstTurnGuide.setEnabled('uno',false);const b=PlayroomAppBridge,r=b.room();b.roomService.configure(r.id,r.ownerId,{firstPlayerMode:'assigned',firstParticipantId:r.ownerId});b.renderLobby();});await active().locator('[data-command=lobby-start]').click();await page.locator('.table-shell').waitFor();if(await page.locator('.handoff [data-command=unlock]').count())await page.locator('.handoff [data-command=unlock]').click();
