  assert.equal(await active().locator('#setting-seating,#setting-scale').count(),0,'geometry follows authored automatic layout');assert.equal(await active().locator('[data-settings-tab]').count(),2);assert.deepEqual(await TestUI.currentSession(page),before,'UI choices preserve the complete durable game');
  await panel.locator('#setting-speed').focus();await page.keyboard.press('Home');assert.equal(await panel.locator('#setting-speed-value').innerText(),await page.evaluate(()=>PlayroomGameFlow.presets.instant.label));assert.equal(await page.evaluate(()=>JSON.parse(localStorage.getItem('playroom.settings.v1')).animationSpeed),'instant');await page.screenshot({path:path.join(shots,`settings-${width}.png`)});
